CREATE TABLE client_receipts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,receipt_code VARCHAR(30) NOT NULL,receipt_number VARCHAR(100) NULL,client_contract_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NOT NULL,client_id BIGINT UNSIGNED NOT NULL,receipt_date DATE NOT NULL,amount DECIMAL(18,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,reference_number VARCHAR(190) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',client_name_snapshot VARCHAR(190) NULL,project_code_snapshot VARCHAR(30) NULL,project_name_snapshot VARCHAR(190) NULL,contract_code_snapshot VARCHAR(30) NULL,contract_number_snapshot VARCHAR(100) NULL,contract_title_snapshot VARCHAR(190) NULL,created_by BIGINT UNSIGNED NOT NULL,posted_at DATETIME NULL,posted_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_client_receipts_code(receipt_code),UNIQUE KEY uq_client_receipts_number(client_contract_id,receipt_number),KEY idx_client_receipts_contract_history(client_contract_id,receipt_date,id),KEY idx_client_receipts_project(project_id,status,receipt_date),KEY idx_client_receipts_client(client_id,status,receipt_date),KEY idx_client_receipts_filters(status,payment_method,receipt_date),CONSTRAINT fk_client_receipts_contract FOREIGN KEY(client_contract_id) REFERENCES client_contracts(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipts_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipts_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipts_created_by FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipts_posted_by FOREIGN KEY(posted_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipts_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_client_receipts_amount CHECK(amount>0),CONSTRAINT chk_client_receipts_method CHECK(payment_method IN('cash','bank_transfer','cheque','other')),CONSTRAINT chk_client_receipts_status CHECK(status IN('draft','posted','cancelled')),CONSTRAINT chk_client_receipts_audit CHECK((status='draft' AND client_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND contract_code_snapshot IS NULL AND contract_number_snapshot IS NULL AND contract_title_snapshot IS NULL AND posted_at IS NULL AND posted_by IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='posted' AND client_name_snapshot IS NOT NULL AND project_code_snapshot IS NOT NULL AND project_name_snapshot IS NOT NULL AND contract_code_snapshot IS NOT NULL AND posted_at IS NOT NULL AND posted_by IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='cancelled' AND client_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND contract_code_snapshot IS NULL AND contract_number_snapshot IS NULL AND contract_title_snapshot IS NULL AND posted_at IS NULL AND posted_by IS NULL AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
